import sys

def lcs_len(a, b):
    n = len(a)
    if n == 0 or len(b) == 0:
        return 0
    M = {}
    for i, c in enumerate(a):
        M[c] = M.get(c, 0) | (1 << i)
    mask = (1 << n) - 1
    V = mask
    get = M.get
    # Precompute complement masks: V = (V + U) | (V & notm)
    pairs = {}
    for c, m in M.items():
        pairs[c] = (m, mask ^ m)
    pg = pairs.get
    z = (0, mask)
    for c in b:
        m, nm = pg(c, z)
        V = ((V + (V & m)) | (V & nm)) & mask
    return n - V.bit_count()

def main():
    data = sys.stdin.read().split("\n")
    a = data[0] if len(data) > 0 else ""
    b = data[1] if len(data) > 1 else ""
    print(lcs_len(a, b))

